SELECT

FROM patient_sleep_record
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
LIMIT 1

SELECT

FROM patient_sleep_record
WHERE patient_id = #{patientId}
  AND is_deleted = 0
ORDER BY wake_time DESC, id DESC
LIMIT #{limit}

SELECT

FROM patient_sleep_record
WHERE patient_id = #{patientId}
  AND is_deleted = 0
  AND wake_time >= #{fromTime}
ORDER BY wake_time DESC, id DESC

mapper.update:
UPDATE patient_sleep_record
SET bedtime = #{bedtime},
    wake_time = #{wakeTime},
    duration_min = #{durationMin},
    quality = #{quality},
    source_type = #{sourceType},
    remark = #{remark}
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0

UPDATE patient_sleep_record
SET is_deleted = 1
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
